grid = input_grid

rectangles = []

def find_rectangles(color):
    """Find maximal rectangular regions of a given color"""
    rects = []
    visited = set()

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color and (r,c) not in visited:
                # Try to expand in all directions
                # BFS to find all connected pixels
                pixels = []
                queue = [(r, c)]
                visited.add((r,c))

                while queue:
                    curr_r, curr_c = queue.pop(0)
                    pixels.append((curr_r, curr_c))

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))

                # Check if pixels form a rectangle
                rows = set(p[0] for p in pixels)
                cols = set(p[1] for p in pixels)
                min_r, max_r = min(rows), max(rows)
                min_c, max_c = min(cols), max(cols)
                expected_count = (max_r - min_r + 1) * (max_c - min_c + 1)

                if len(pixels) == expected_count:
                    rects.append((min_r, min_c, max_r - min_r + 1, max_c - min_c + 1, len(pixels)))

    return rects

