def find_containers(grid):
    """Find connected regions that could act as containers"""
    containers = {}

    # Use flood fill to find connected non-0, non-background components
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            color = grid[r][c]
            if color == 0 or color == 3:  # skip holes and background
                continue

            # BFS for connected component
            visited = {(r, c)}
            component = []
            queue = [(r, c)]

            while queue:
                curr_r, curr_c = queue.pop(0)
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = curr_r + dr, curr_c + dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        if (nr, nc) not in visited and grid[nr][nc] == color:
                            visited.add((nr, nc))
                            component.append((nr, nc))
                            queue.append((nr, nc))

            if len(component) > 5:  # Only larger components
                containers[color] = component

    return containers

